const targets = $('Target Company Slugs').all().map((item) => item.json);
const inputs = $input.all();
const targetKeywords = /\b(systems admin|system administrator|it manager|it lead|infrastructure|cloud engineer|security engineer|systems engineer|it operations|devops|mcp|n8n)\b/i;
const exclusionKeywords = /\b(active secret clearance|top secret\/sci|ts\/sci)\b/i;
const seenInThisRun = new Set();
const normalized = [];

for (let sourceIndex = 0; sourceIndex < inputs.length; sourceIndex += 1) {
  const response = inputs[sourceIndex].json;
  if (!response || response.error) continue;

  let body = response.data;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      continue;
    }
  }

  const source = targets[sourceIndex] || {};
  let jobs = [];
  if (Array.isArray(body)) jobs = body;
  else if (body && Array.isArray(body.jobs)) jobs = body.jobs;
  else if (body && Array.isArray(body.postings)) jobs = body.postings;
  else if (body && Array.isArray(body.data)) jobs = body.data;

  for (const job of jobs) {
    const externalId = job.id || job.job_id;
    if (externalId === undefined || externalId === null || String(externalId).trim() === '') continue;
    const jobId = String(externalId);
    if (seenInThisRun.has(jobId)) continue;

    const title = job.title || '';
    const description = job.content || job.description || job.descriptionHtml || '';
    if (exclusionKeywords.test(description)) continue;
    if (!targetKeywords.test(title) && !targetKeywords.test(description)) continue;

    seenInThisRun.add(jobId);
    const categories = job.categories && typeof job.categories === 'object' ? job.categories : {};
    const jobLocation = job.location && typeof job.location === 'object' ? job.location.name : job.location;
    normalized.push({
      json: {
        job_id: jobId,
        title,
        company: job.company || job.company_name || categories.company || source.company || 'Unknown',
        location: jobLocation || categories.location || 'Remote',
        url: job.absolute_url || job.hostedUrl || job.url || job.jobUrl || job.applyUrl || '',
        raw_text: description.slice(0, 3000)
      }
    });
  }
}

return normalized;

