const rawOutput = $json.output !== undefined ? $json.output : ($json.text !== undefined ? $json.text : $json);
const parsedRoot = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
const parsed = parsedRoot && parsedRoot.output && typeof parsedRoot.output === 'object' ? parsedRoot.output : parsedRoot;
const job = $('Restore Job Payload').item.json;
const emojiPattern = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2702}-\u{27B0}\u{1F900}-\u{1F9FF}\u{1FA70}-\u{1FAFF}]+/gu;
const result = { ...parsed };
for (const key of Object.keys(result)) {
  if (typeof result[key] === 'string') result[key] = result[key].replace(emojiPattern, '');
  else if (Array.isArray(result[key])) result[key] = result[key].map((value) => typeof value === 'string' ? value.replace(emojiPattern, '') : value);
}
return { json: { ...result, job_id: job.job_id, title: job.title, company: job.company, location: job.location, url: job.url } };

const results = $('Attach Job Metadata').all().map((item) => item.json);
const highFit = results.filter((result) => Number(result.fit_score) >= 7).sort((a, b) => Number(b.fit_score) - Number(a.fit_score));
const selected = highFit.slice(0, 20);
if (selected.length === 0) return [];
return [{ json: { evaluated_count: results.length, high_fit_count: highFit.length, alert_count: selected.length, results: selected } }];
